import {loadConfig} from './connection.mjs';
import {totals,loanTerms,interest} from './paper-math.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n/100).toLocaleString('en-US',{style:'currency',currency:'USD'}),signed=n=>(n<0?'−':'+')+money(Math.abs(n)),time=t=>t?new Date(t).toLocaleString('en-US',{timeZone:'America/New_York',timeZoneName:'short'}):'Not started';
let initializing=null;
let session=null,config=null,data=null,view=location.hash.slice(1)||'trading',busy=false;
try{session=JSON.parse(sessionStorage.getItem('market-lab:auth:v1')||'null');}catch{}
function authSave(){if(session)sessionStorage.setItem('market-lab:auth:v1',JSON.stringify(session));else sessionStorage.removeItem('market-lab:auth:v1');}
async function token(){if(!session)throw Error('Sign in first.');if(session.expires_at*1000<Date.now()+60000){const r=await fetch(config.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){session=null;authSave();throw Error('Session expired. Sign in again.');}session=await r.json();authSave();}return session.access_token;}
async function api(path,body){const r=await fetch('/api/lab/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+await token(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Workspace access failed');return d;}
function metric(label,value,cls=''){return `<div class="metric"><label>${label}</label><div class="value ${cls}">${value}</div></div>`;}
function agentHead(a){return `<div class="agent"><span class="avatar">${a.id==='A'?'A1':'A2'}</span><div><h2>${esc(a.name||'Agent '+(a.id==='A'?'1':'2'))}</h2><span class="small">${a.id==='A'?'15-minute trader':'Flexible horizon · up to 30 days'} · ${a.name?'Self-chosen name':'Name pending first API decision'}</span></div></div>`;}
function account(a,detailed=false){const t=totals(a);return `<article class="panel">${agentHead(a)}<div class="metrics">${metric('Available cash',money(t.cash))}${metric('Invested at cost',money(t.invested))}${metric('Realized made / lost',signed(t.realized),t.realized<0?'negative':'positive')}</div>${detailed?`<dl>${[['Starting fake capital',money(a.start)],['Estimated open-position value',money(t.value)],['Unrealized change',signed(t.unrealized)],['Outstanding principal',money(t.debt)],['Accrued interest owed',money(t.interest)],['Interest already paid',money(a.interestPaid)],['Trading fees paid',money(a.fees)],['Net value after debt & interest',money(t.net)],['Total return',t.returnPct.toFixed(2)+'%'],['Largest drawdown',money(a.maxDrawdown)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="note">Profit is a running result, not a second cash wallet. Borrowing increases cash and debt equally. Open-position marks may be stale or not executable.</div>`:`<p class="small">${esc(a.status||'Waiting for the worker')} · ${a.positions.length} open position(s) · ${a.orders.length} pending order(s)</p><div class="decision"><h3>Latest decision</h3><p>${esc(a.decision?.summary||'No model decision recorded yet.')}</p><small>${time(a.decision?.at)}</small></div>${a.decision?`<details><summary>Evidence, plan & lesson</summary><p>${esc(a.decision.evidence)}</p><p><strong>Exit / repayment plan:</strong> ${esc(a.decision.exitPlan)}</p><p><strong>Research hypothesis:</strong> ${esc(a.decision.lesson)}</p><small>${esc(a.decision.model)} · ${esc(a.decision.promptVersion)} · Probability estimate is unverified</small></details>`:''}<hr class="divider">${a.positions.map(p=>`<p><strong>${esc(p.side)} · ${p.quantity} contracts</strong><small>${esc(p.market)} · cost ${money(p.cost)} · estimated value ${money(p.mark??p.cost)}${p.markStale?' · STALE MARK':''}</small></p>`).join('')||'<p class="small">No open position. Keeping cash is allowed.</p>'}${a.orders.map(o=>`<p class="small">Pending ${esc(o.action)} ${esc(o.side)} · ${esc(o.market)} · limit ${(o.limit/100).toFixed(2)}¢</p>`).join('')}`}</article>`;}
function trading(){return `<div class="grid">${data.state.agents.map(a=>account(a)).join('')}<section class="panel full"><h2>Activity & decision journal</h2>${data.events.map(event).join('')||'<p class="muted">No events yet. The worker is not inventing activity.</p>'}</section></div>`;}
function event(e){return `<div class="trade"><span class="small">${time(e.at)}</span><div><strong>${esc(e.agent?'Agent '+(e.agent==='A'?'1':'2')+' · ':'')}${esc(e.type)}</strong><p>${esc(e.reason||e.detail||e.decision?.summary||e.application?.reason||'Recorded ledger event')}</p>${e.market?`<small>${esc(e.market)} · ${esc(e.side||'')} ${e.quantity??''}</small>`:''}<details><summary>Recorded details</summary><p>${esc(JSON.stringify(e))}</p></details></div><span>${e.fee!==undefined?'Fee '+money(e.fee):e.amount?money(e.amount):''}</span></div>`;}
function accounts(){return `<div class="grid">${data.state.agents.map(a=>account(a,true)).join('')}<section class="panel full"><h2>Review checkpoints</h2><p>Days 10, 20, and 30 from ${time(data.state.startedAt)}. Open positions and unsettled outcomes remain separate.</p>${data.state.checkpoints.map(r=>`<h3>Day ${r.day} · ${time(r.at)}</h3>${r.accounts.map(a=>`<p>Agent ${a.id}: net ${money(a.net)} · realized ${signed(a.realized)}</p>`).join('')}`).join('')||'<p class="small">No checkpoint reached yet.</p>'}</section></div>`;}
function bank(){const s=data.state,apps=s.agents.flatMap(a=>a.applications.map(x=>({...x,agent:a.id}))).toReversed(),principal=s.agents.reduce((n,a)=>n+totals(a).debt,0);return `<div class="banktop">${metric('Available to lend',money(s.bank.available))}${metric('Outstanding principal',money(principal))}${metric('Pending requests',apps.filter(x=>x.status==='pending').length)}</div>${apps.map(x=>`<article class="panel loan"><div class="row"><h2>Agent ${x.agent==='A'?'1':'2'} requests ${money(x.amount)}</h2><span class="badge">${esc(x.status)}</span></div><p>${esc(x.reason)}</p><dl><div><dt>Annual simple interest</dt><dd>${x.apr}%</dd></div><div><dt>Interest for 30 days on requested amount</dt><dd>${money(Math.ceil(x.amount*x.apr/100*30/365))}</dd></div><div><dt>Term</dt><dd>Due 30 days after funding; early repayment allowed</dd></div></dl>${x.status==='pending'?`<label>Approve amount ($)<input type="number" min="1" max="${x.amount/100}" step="0.01" value="${x.amount/100}" data-amount="${esc(x.id)}"></label><div class="actions"><button class="primary" data-loan="${esc(x.id)}" data-approve="true">Approve fake loan</button><button data-loan="${esc(x.id)}" data-approve="false">Deny</button></div>`:`<p class="small">Reviewed ${time(x.reviewedAt)}${x.approvedAmount?' · Funded '+money(x.approvedAmount):''}</p>`}</article>`).join('')||'<section class="panel"><h2>No applications yet</h2><p>An agent must submit a request with its plan before you can approve it.</p></section>'}<section class="panel"><h2>Bank policy · 23% starting annual interest</h2><p>First loan: up to $50 / $250. After successful repayment: up to $100 / $500. Additional borrowing with unpaid debt: up to $25 / $125 at 28%, then $10 / $50 at 33%. No further supplemental loans until debt is cleared.</p><p>Outstanding principal never exceeds $100 for Agent 1 or $500 for Agent 2. Every loan requires your approval; existing loans keep their agreed rates.</p>${s.agents.map(a=>`<h3>${esc(a.name||'Agent '+a.id)}</h3><p class="small">Current maximum new request: ${money(loanTerms(a).limit)} at ${loanTerms(a).apr}% annually</p>${a.loans.map(l=>`<p>Principal ${money(l.principal)} · interest ${money(interest(l))} · ${l.apr}% annual · due ${time(l.dueAt)}${l.dueAt<Date.now()?' · OVERDUE':''}</p>`).join('')}`).join('')}</section>`;}
function markets(){return `<div class="notice">Actual Kalshi public REST observations. No embedded Kalshi account and no real orders. Asks are derived from opposite-side bids. Receipt time does not prove exchange quote freshness. Universe: BTC 15-minute and selected KXBTC / KXBTCD contracts, not every Kalshi market.</div><div class="grid">${data.state.markets.map(m=>`<article class="panel market"><div class="row"><span class="badge">${esc(m.status)}</span><span class="small">${esc(m.series)}</span></div><h2>${esc(m.title)}</h2><p>${esc(m.yes_sub_title||m.subtitle||'')}</p><small>${esc(m.ticker)}</small><div class="quote"><div><span class="small">YES bid</span><strong>${m.quotes?.yesBid?(m.quotes.yesBid.price/100).toFixed(2)+'¢':'Unavailable'}</strong></div><div><span class="small">YES ask · derived</span><strong>${m.quotes?.yesAsk?(m.quotes.yesAsk.price/100).toFixed(2)+'¢':'Unavailable'}</strong></div></div><dl><div><dt>Received</dt><dd>${time(m.receivedAt)}${Date.now()-Date.parse(m.receivedAt)>90000?' · STALE':''}</dd></div><div><dt>Trading close</dt><dd>${time(m.close_time)}</dd></div><div><dt>Expected latest settlement</dt><dd>${time(m.latest_expiration_time||m.expiration_time)}</dd></div><div><dt>Official target</dt><dd>${m.floor_strike??'Unavailable'}</dd></div><div><dt>General taker fee model verified</dt><dd>${m.feeVerified?'Series quadratic multiplier '+m.multiplier:'NO — fills blocked'}</dd></div></dl><details><summary>Official market rules</summary><p>${esc(m.rules_primary||'Unavailable')}</p><p>${esc(m.rules_secondary||'')}</p></details></article>`).join('')||'<section class="panel"><h2>No observations received yet</h2><p>Start the paper worker after cloud configuration is verified.</p></section>'}</div>`;}
function render(){if(!data)return;const s=data.state;$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;const pages={trading:['Watch the experiment','The trading floor','Real observations. API decisions. Simulated fills.'],accounts:['Cash, positions & performance','Agent accounts','Separate balances; profits and losses stay visible.'],bank:['Your approval releases funds','The paper bank','Applications never guarantee funding.'],markets:['Public exchange observations','Kalshi markets','Official quotes, rules, and outcomes; no live-money connection.']};if(!pages[view])view='trading';const p=pages[view];$('#eyebrow').textContent=p[0];$('#title').textContent=p[1];$('#subtitle').textContent=p[2];document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const stale=!s.lastTick||Date.now()-Date.parse(s.lastTick)>180000;$('#run-status').textContent=`${config.workerConfigured===false?'CLOUD CREDENTIAL SETUP REQUIRED · ':''}${s.mode.toUpperCase()} · ${s.phase==='verification'?'SHORT VERIFICATION':'30-DAY EXPERIMENT'}${stale?' · WORKER STALE / NOT STARTED':''} · Last tick ${time(s.lastTick)} · Estimated API spend $${s.budget.spent.toFixed(3)} / $${s.budget.cap} ($${s.budget.dailyCap}/UTC day) · Key safety stop ${time(s.keyExpiresAt)}${s.error?' · '+s.error:''}`;$('#start').disabled=s.mode==='running'||config.workerConfigured===false;$('#pause').disabled=s.mode!=='running';$('#content').innerHTML=({trading,accounts,bank,markets})[view]();}
async function refresh(){if(!session||busy)return;busy=true;try{data=await api('state');render();}catch(e){$('#message').textContent=e.message;if(!session){$('#login').hidden=false;$('#dashboard').hidden=true;}}finally{busy=false;}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(!config){await initialize();if(!config)return;}$('#login-error').textContent='';try{const r=await fetch(config.url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({email:f.email.value,password:f.password.value})});const d=await r.json();if(!r.ok)throw Error('Sign-in failed. Check your DS HUB credentials.');session=d;authSave();f.password.value='';await refresh();}catch(e){$('#login-error').textContent=e.message;}});
$('#logout').addEventListener('click',()=>{session=null;authSave();location.reload();});
async function control(action,p={}){try{$('#message').textContent='Saving…';await api('control',{action,...p});$('#message').textContent='Saved.';await refresh();}catch(e){$('#message').textContent=e.message;}}
$('#start').addEventListener('click',()=>control('start'));$('#pause').addEventListener('click',()=>control('pause'));
$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-loan]');if(!b)return;const input=[...document.querySelectorAll('[data-amount]')].find(x=>x.dataset.amount===b.dataset.loan);control('loan',{id:b.dataset.loan,amount:Math.round(Number(input.value)*100),approve:b.dataset.approve==='true'});});
$('#export').addEventListener('click',async()=>{if(!data)return;try{const events=[];let after=0;while(true){const batch=await api('history?after='+after);events.push(...batch.events);$('#message').textContent='Exporting '+events.length+' recorded events…';if(batch.events.length<500)break;after=batch.events.at(-1).recordId;}const blob=new Blob([JSON.stringify({kind:'market-lab-cloud-export',version:'0.4.2',exportedAt:new Date().toISOString(),...data,events},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='DS-Market-Lab-0.4.2-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#message').textContent='Exported '+events.length+' events and current accounts. Raw recordings remain in the archive.';}catch(e){$('#message').textContent='Export failed: '+e.message;}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);render();});setInterval(()=>{if(!document.hidden&&!document.querySelector('[data-amount]:focus'))refresh();},15000);
async function initialize(){
 if(initializing)return initializing;
 initializing=(async()=>{const submit=$('#login-form button'),retry=$('#retry-connection');submit.disabled=true;retry.disabled=true;$('#connection-status').textContent='Connecting to your lab…';
 try{config=await loadConfig();submit.disabled=false;retry.hidden=true;$('#login-error').textContent='';$('#connection-status').textContent='Connected · Ready to sign in';if(session)await refresh();}
 catch(error){config=null;$('#connection-status').textContent='Connection interrupted';$('#login-error').textContent=error.message;retry.hidden=false;}
 finally{retry.disabled=false;initializing=null;}
 })();return initializing;
}
$('#retry-connection').addEventListener('click',()=>initialize());
window.addEventListener('online',()=>{if(!config)initialize();});
window.addEventListener('pageshow',()=>{if(!config)initialize();});
await initialize();
